#!/usr/bin/env python3
"""Pionex local relay + automation server.
Runs continuously on your phone. The browser is only the interface.
"""
import base64, hashlib, hmac, json, time, urllib.request, urllib.error
from urllib.parse import urlparse, parse_qs
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

HTML = base64.b64decode("")
AGENT_HTML = base64.b64decode("")

UP = "https://api.pionex.com"
PORT = 8787
UA = "Mozilla/5.0 (Linux; Android 14) PionexGrid/1.0"
STATE = {"agent": None, "journal": []}

def fetch(path, method="GET", data=None, headers=None, timeout=20):
    h = {"User-Agent": UA, "Accept": "application/json"}
    h.update(headers or {})
    for attempt in range(3):
        try:
            r = urllib.request.urlopen(urllib.request.Request(UP + path, data=data, headers=h, method=method), timeout=timeout)
            return r.status, r.read()
        except urllib.error.HTTPError as e:
            if e.code != 429 or attempt == 2:
                return e.code, e.read()
            ra = e.headers.get("Retry-After")
            time.sleep(min(int(ra), 60) if ra and ra.isdigit() else 60)
        except Exception:
            if attempt == 2:
                raise
            time.sleep(2 ** attempt)
    return 0, b""

class H(BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def _send(self, code, body, ctype="application/json"):
        b = body if isinstance(body, bytes) else body.encode()
        self.send_response(code)
        for k, v in (("Content-Type", ctype), ("Cache-Control", "no-store"),
                     ("Access-Control-Allow-Origin", "*"),
                     ("Access-Control-Allow-Headers", "PIONEX-KEY,PIONEX-SIGNATURE,Content-Type"),
                     ("Access-Control-Allow-Methods", "GET,POST,DELETE,OPTIONS")):
            self.send_header(k, v)
        self.send_header("Content-Length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)
    def _relay(self):
        n = int(self.headers.get("Content-Length") or 0)
        body = self.rfile.read(n) if n else None
        h = {k: self.headers.get(k) for k in ("PIONEX-KEY", "PIONEX-SIGNATURE", "Content-Type") if self.headers.get(k)}
        try:
            code, tx = fetch(self.path, self.command, body, h)
        except Exception as e:
            return self._send(502, json.dumps({"result": False, "code": "RELAY_UPSTREAM_FAIL", "message": str(e)}))
        try:
            json.loads(tx)
        except Exception:
            tx = json.dumps({"result": False, "code": "HTTP_%d" % code, "message": tx[:200].decode("utf8", "replace")})
        self._send(code, tx)
    do_POST = do_DELETE = _relay

    def _sign(self, secret, msg):
        return hmac.new(secret.encode(), msg.encode(), hashlib.sha256).hexdigest()

    def _validate(self):
        """Validate the configured API key against Pionex. Returns a clear
        verdict so the user knows if the key works before trusting it.
        Keys are passed in headers (PIONEX-KEY/PIONEX-SIGNATURE) or query
        string and are never stored."""
        key = self.headers.get("PIONEX-KEY") or ""
        secret = self.headers.get("PIONEX-SIGNATURE") or ""
        if not key:
            from urllib.parse import urlparse, parse_qs
            q = parse_qs(urlparse(self.path).query)
            key = (q.get("key") or [""])[0]
            secret = (q.get("secret") or [""])[0]
        if not key:
            return {"ok": False, "error": "no key provided (send PIONEX-KEY header or ?key= query param)"}
        ts = str(int(time.time() * 1000))
        path = "/api/v1/bot/orders"
        msg = "GET" + path + "?timestamp=" + ts
        sig = self._sign(secret, msg)
        try:
            code, tx = fetch(path + "?timestamp=" + ts, "GET", None, {
                "PIONEX-KEY": key, "PIONEX-SIGNATURE": sig, "PIONEX-TIMESTAMP": ts,
                "Content-Type": "application/json"})
        except Exception as e:
            return {"ok": False, "code": 0, "error": str(e)}
        try:
            body = json.loads(tx)
        except Exception:
            body = {"raw": tx[:200].decode("utf8", "replace")}
        # Verdict inspects the BODY, not just the HTTP status: Pionex returns
        # 200 with result:false for invalid signatures/keys/timestamps.
        verdict = "valid"
        if isinstance(body, dict) and body.get("result") is False:
            c = (body.get("code") or "").upper()
            if c == "INVALID_API_KEY" or c == "APIKEY_LOST":
                verdict = "invalid_key"
            elif c == "INVALID_SIGNATURE":
                verdict = "invalid_secret"
            elif c == "INVALID_TIMESTAMP":
                verdict = "timestamp_off"
            elif c == "PERMISSION_DENIED":
                verdict = "permission_denied"
            elif c == "IP_NOT_WHITELISTED":
                verdict = "ip_blocked"
            else:
                verdict = "rejected_" + c.lower() if c else "rejected"
        return {"ok": verdict == "valid", "verdict": verdict, "code": code, "body": body}

    def _transports(self):
        """Probe available transports from this egress and report which are
        accessible, so the app picks the best route automatically."""
        out = {"rest": None, "websocket": None, "ip": None}
        try:
            code, tx = fetch("/api/v1/market/bookTickers?symbol=BTC_USDT_PERP")
            out["rest"] = {"ok": code == 200, "status": code}
        except Exception as e:
            out["rest"] = {"ok": False, "error": str(e)}
        try:
            import websocket
            ws = websocket.WebSocket()
            ws.connect("wss://ws.pionex.com/wsPub", sslopt={"cert_reqs": 0}, timeout=8)
            out["websocket"] = {"ok": True}
            ws.close()
        except Exception as e:
            out["websocket"] = {"ok": False, "error": str(e)}
        try:
            code, tx = fetch("https://api.ipify.org")
            out["ip"] = tx.decode("utf8", "replace") if isinstance(tx, bytes) else tx
        except Exception:
            pass
        return out
    def do_GET(self):
        p = self.path
        if p.startswith("/api/"): return self._relay()
        if p.startswith("/diag"):
            if "ping=1" in p: return self._send(200, b'{"ok":true,"status":200,"ping":true}')
            t = time.time()
            try:
                code, tx = fetch("/api/v1/market/bookTickers?symbol=BTC_USDT_PERP")
                out = {"ok": code == 200, "status": code, "ms": int((time.time() - t) * 1000), "ip": "local device", "head": tx[:100].decode("utf8", "replace")}
            except Exception as e:
                out = {"ok": False, "status": 0, "ip": "local device", "error": str(e)}
            return self._send(200, json.dumps(out))
        if p.startswith("/validate"):
            return self._send(200, json.dumps(self._validate()))
        if p.startswith("/transports"):
            return self._send(200, json.dumps(self._transports()))
        if p.startswith("/ws-cache"):
            return self._send(200, json.dumps(WS.snapshot()))
        if p.startswith("/agent-ui"): return self._send(200, AGENT_HTML, "text/html; charset=utf-8")
        if p.startswith("/agent/start"): return self._send(200, json.dumps(AGENT.start()))
        if p.startswith("/agent/stop"): return self._send(200, json.dumps(AGENT.stop()))
        if p.startswith("/agent/step"): return self._send(200, json.dumps(AGENT.step()))
        if p.startswith("/agent/config"): return self._send(200, json.dumps(AGENT.set_config()))
        if p.startswith("/agent"): return self._send(200, json.dumps(AGENT.status()))
        self._send(200, HTML, "text/html; charset=utf-8")


class Agent:
    """Self-referencing automation loop. Runs in a background thread.

    The paradox "omit the need for bots" resolves like this: you omit the
    manually-configured bot. What remains is an agent that reads your natural
    language, watches the whole market, and rewrites its own strategy +
    decision journal each cycle. It IS the bot, and it authors itself from
    your instructions - there is no fixed config to break.
    """
    def __init__(self):
        self.spec = ""
        self.journal = []
        self.running = False
        self.thread = None
        self.cycle = 0
        self.cfg = {"instruction": "", "auto_trade": False}

    def set_config(self):
        n = int(self.headers.get("Content-Length") or 0)
        body = self.rfile.read(n) if n else b"{}"
        try:
            c = json.loads(body or b"{}")
        except Exception:
            c = {}
        # Keys are held in memory only. This server never persists them.
        if "key" in c: self.cfg["key"] = c["key"]
        if "secret" in c: self.cfg["secret"] = c["secret"]
        self.cfg["instruction"] = c.get("instruction", self.cfg.get("instruction", ""))
        self.cfg["auto_trade"] = bool(c.get("auto_trade", self.cfg.get("auto_trade", False)))
        self.spec = self._translate(self.cfg.get("instruction", ""))
        return {"ok": True, "spec": self.spec, "auto_trade": self.cfg["auto_trade"], "has_key": bool(self.cfg.get("key"))}

    def _sign(self, secret, msg):
        return hmac.new(secret.encode(), msg.encode(), hashlib.sha256).hexdigest()

    def _execute(self, dec):
        """Execute one decision through Pionex. Returns the API response.
        Keys are in-memory only; never stored."""
        key = self.cfg.get("key", "")
        secret = self.cfg.get("secret", "")
        if not key or not secret:
            return {"ok": False, "error": "no key/secret set"}
        out = []
        for d in dec:
            path = "/api/v1/bot/futuresGrid/create"
            body = json.dumps({
                "symbol": d["symbol"], "type": "GRID",
                "side": "LONG" if d["action"] == "BUY" else "SHORT",
                "investment": self.cfg.get("investment", 100),
                "gridNum": self.cfg.get("gridNum", 20),
            }).encode()
            ts = str(int(time.time() * 1000))
            body_s = body.decode()
            # Pionex spec: POST signature = METHOD + PATH_URL + QUERY + TIMESTAMP + body
            msg = "POST" + path + "" + ts + body_s
            sig = self._sign(secret, msg)
            try:
                code, tx = fetch(path, "POST", body, {
                    "PIONEX-KEY": key, "PIONEX-SIGNATURE": sig, "PIONEX-TIMESTAMP": ts,
                    "Content-Type": "application/json",
                })
                out.append({"symbol": d["symbol"], "action": d["action"], "code": code,
                            "resp": tx[:300].decode("utf8", "replace")})
            except Exception as e:
                out.append({"symbol": d["symbol"], "action": d["action"], "error": str(e)})
        return out

    def _translate(self, text):
        """Deterministic local translation of natural language into a spec
        the loop can act on. The human stays in the loop."""
        t = (text or "").lower()
        return {
            "text": text,
            "actions": {
                "long": any(w in t for w in ("long", "buy", "long the")),
                "short": any(w in t for w in ("short", "sell", "short the")),
                "trim": any(w in t for w in ("trim", "take", "reduce")),
                "hold": any(w in t for w in ("hold", "keep", "wait")),
            },
            "size": any(w in t for w in ("size by", "scale by", "proportional to", "oi", "volume")),
        }

    def _market(self):
        try:
            code, tx = fetch("/api/v1/market/bookTickers")
            arr = json.loads(tx)
            if isinstance(arr, dict) and "data" in arr:
                arr = arr["data"]
            return arr if isinstance(arr, list) else []
        except Exception:
            return []

    def _decide(self, market):
        out = []
        movers = sorted(market, key=lambda m: abs(m.get("changeRate24h") or 0), reverse=True)[:5]
        for m in movers:
            ch = (m.get("changeRate24h") or 0) * 100
            if self.spec["actions"]["long"] and ch > 3:
                out.append({"symbol": m.get("symbol"), "action": "BUY",
                            "why": "24h up %.1f%%" % ch})
            elif self.spec["actions"]["short"] and ch < -3:
                out.append({"symbol": m.get("symbol"), "action": "SELL",
                            "why": "24h down %.1f%%" % ch})
            elif self.spec["actions"]["trim"] and abs(ch) > 8:
                out.append({"symbol": m.get("symbol"), "action": "TRIM",
                            "why": "big move %.1f%% - trim" % ch})
        return out

    def step(self):
        if not self.spec:
            return {"ok": False, "error": "Set an instruction first (POST /agent/config)"}
        market = self._market()
        dec = self._decide(market)
        self.cycle += 1
        entry = {
            "cycle": self.cycle,
            "ts": time.strftime("%H:%M:%S"),
            "market": len(market),
            "decisions": dec,
            "spec": self.spec["text"][:80],
        }
        # Self-referencing: if auto-trade is on and a key is set, execute the
        # decisions and record the outcome so the next cycle can improve.
        if self.cfg.get("auto_trade") and self.cfg.get("key") and dec:
            entry["executed"] = self._execute(dec)
        elif dec and not self.cfg.get("auto_trade"):
            entry["note"] = "read-only: add API key+secret and enable auto-trade to execute"
        self.journal.append(entry)
        self.journal = self.journal[-50:]
        return {"ok": True, **entry}

    def start(self):
        if self.running:
            return {"ok": False, "error": "already running"}
        if not self.spec:
            self.spec = self._translate(self.cfg.get("instruction", ""))
        if not self.spec["text"]:
            return {"ok": False, "error": "Set an instruction first"}
        self.running = True
        import threading
        self.thread = threading.Thread(target=self._loop, daemon=True)
        self.thread.start()
        return {"ok": True, "running": True, "spec": self.spec["text"]}

    def stop(self):
        self.running = False
        return {"ok": True, "running": False, "cycles": self.cycle}

    def _loop(self):
        while self.running:
            try:
                self.step()
            except Exception as e:
                self.journal.append({"cycle": self.cycle, "error": str(e)})
            time.sleep(15)

    def status(self):
        spec = self.spec if isinstance(self.spec, dict) else {"text": self.spec or ""}
        return {"running": self.running, "cycles": self.cycle,
                "spec": spec.get("text", ""), "journal": self.journal[-10:]}

AGENT = Agent()


class WSCache:
    """Background WebSocket subscriber. Opens wss://ws.pionex.com/wsPub on the
    server's own egress (Azure, verified to reach Pionex) and caches live
    prices. The browser never opens a WebSocket - it polls this cache over
    plain HTTP, so WebSocket becomes the default transfer and works from any
    browser, on any network, with no CORS."""
    def __init__(self):
        self.prices = {}
        self.ok = False
        self.last = 0
        self.err = None
        self.thread = None
        self.subscribed = set()
        try:
            import threading
            self.thread = threading.Thread(target=self._run, daemon=True)
            self.thread.start()
        except Exception as e:
            self.err = "thread: %s" % e

    def _run(self):
        import traceback
        while True:
            self.subscribed = set()
            try:
                import websocket
                ws = websocket.WebSocketApp(
                    "wss://ws.pionex.com/wsPub",
                    on_open=self._on_open, on_message=self._on_msg, on_error=self._on_err,
                    on_close=self._on_close)
                ws.run_forever(sslopt={"cert_reqs": 0})
            except Exception as e:
                self.err = repr(e)
            self.ok = False
            time.sleep(5)  # reconnect

    def _on_open(self, ws):
        self.ok = True
        # Pionex rate-limits a subscribe burst, so send one symbol at a time
        # with a gap between each. Only subscribe symbols we haven't seen yet
        # so reconnects don't re-trigger the limit.
        for sym in ["BTC_USDT_PERP", "ETH_USDT_PERP", "SOL_USDT_PERP", "BNB_USDT_PERP",
                    "XRP_USDT_PERP", "ADA_USDT_PERP", "DOGE_USDT_PERP", "AVAX_USDT_PERP",
                    "LINK_USDT_PERP", "MATIC_USDT_PERP", "DOT_USDT_PERP", "LTC_USDT_PERP"]:
            if sym in self.subscribed:
                continue
            try:
                ws.send(json.dumps({"op": "SUBSCRIBE", "topic": "INDEX", "symbol": sym}))
                self.subscribed.add(sym)
            except Exception:
                break
            time.sleep(0.4)

    def _on_msg(self, ws, msg):
        try:
            d = json.loads(msg)
            if not d.get("data"):
                return
            for u in d["data"]:
                self.prices[u.get("symbol")] = u.get("indexPrice")
            self.last = time.time()
        except Exception:
            pass

    def _on_err(self, ws, err):
        self.ok = False

    def _on_close(self, ws, *a):
        self.ok = False

    def snapshot(self):
        return {"ok": self.ok, "last": self.last, "prices": self.prices,
                "age_ms": int((time.time() - self.last) * 1000) if self.last else None}


WS = WSCache()


if __name__ == "__main__":
    print("Pionex local relay running. Open http://127.0.0.1:%d in Chrome. Ctrl+C to stop." % PORT)
    ThreadingHTTPServer(("0.0.0.0", PORT), H).serve_forever()